import { Component, createMemo, createSignal, For, Show } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";
import {
	Focusable,
	focusableToString,
	FocusContextProvider,
	getFocusableElement,
	isFocusableAFocusContext,
	rootFocus,
} from "#core/ui-next/services/focus.js";

import style from "./focus-viewer.scss?url";

interface FocusTreeNodeProps {
	focusable: Focusable;
	focusLevel: number;
	isDefault: boolean;
}

const FocusTreeNode: Component<FocusTreeNodeProps> = (props) => {
	const [isHovered, setIsHovered] = createSignal(false);

	const focusClass = createMemo(() => `level-${props.focusLevel}`);
	const focusManager = FocusManager.get();

	const children = () => {
		return isFocusableAFocusContext(props.focusable) ? props.focusable.children() : [];
	};

	const element = createMemo(() => getFocusableElement(props.focusable));
	const currentFocus = createMemo(() => (props.focusable as FocusContextProvider)?.currentFocus?.());
	const isFocused = createMemo(() => focusManager.activeElement() == element());

	function startHighlight() {
		const currentElement = element();

		// don't add border to the body to avoid jarring fullscreen outline that moves the entire viewport
		if (currentElement?.isConnected && currentElement != document.body) {
			currentElement.classList.add("debug-focus", focusClass());
		}
		setIsHovered(true);
	}

	function endHighlight() {
		const currentElement = element();
		if (currentElement?.isConnected) {
			currentElement.classList.remove("debug-focus", focusClass());
		}
		setIsHovered(false);
	}

	return (
		<div
			class="flex flex-col pointer-events-auto"
			on:mouseenter={() => startHighlight()}
			on:mouseleave={() => endHighlight()}
		>
			<div
				class={`min-w-64 p-1 debug-focus focus-item ${isHovered() ? focusClass() : ""}`}
				classList={{ focus: isFocused(), "default-focus": props.isDefault }}
			>
				{focusableToString(props.focusable)}
			</div>
			<div class="flex flex-col ml-6">
				<For each={children()}>
					{(focusable) => (
						<>
							<div />
							<FocusTreeNode
								focusable={focusable}
								focusLevel={props.focusLevel + 1}
								isDefault={focusable == currentFocus()}
							/>
						</>
					)}
				</For>
			</div>
		</div>
	);
};

export interface FocusViewerComponentProps {
	initialVisibility?: boolean;
}

/**
 * A debug viewer that displays the current focus tree and allows interaction with it.
 * @param props {@link FocusViewerComponentProps}
 * @returns
 */
const FocusViewerComponent: Component<FocusViewerComponentProps> = (props) => {
	const [isVisible, setIsVisible] = createSignal(props.initialVisibility);

	const icon = createMemo(() => (isVisible() ? "Action_Sleep" : "Action_Wake"));

	return (
		<div
			class="absolute max-w-128 h-screen right-0 top-0 bottom-0 flex flex-col items-end justify-start"
			style={{ "z-index": 99999 }}
		>
			<Activatable
				disableFocus={true}
				class="border-2 size-16 border-white self-end m-4"
				onActivate={() => setIsVisible((collapsed) => !collapsed)}
			>
				<Icon
					class="size-16"
					name={icon()}
				/>
			</Activatable>
			<Show when={isVisible()}>
				<ScrollArea class="flex flex-col flex-auto">
					<FocusTreeNode
						focusable={rootFocus}
						focusLevel={0}
						isDefault={true}
					/>
				</ScrollArea>
			</Show>
		</div>
	);
};

export const FocusViewer = ComponentRegistry.register({
	name: "FocusViewer",
	createInstance: FocusViewerComponent,
	styles: [style],
});

export const FxsFocusViewer = defineLegacyComponent("fxs-focus-viewer", {}, FocusViewerComponent);
